const boughtTogether = `-- name: BoughtTogether :many
SELECT
    p.slug,
    localized_name(p.name, p.name_en, $1::text) AS name,
    coalesce(localized_name(p.summary, p.summary_en, $1::text), '')::text AS summary,
    b.name AS brand,
    mv.price_cents AS min_price_cents,
    mv.compare_at_price_cents,
    coalesce(rv.rating, 0)::float8 AS rating,
    coalesce(rv.n, 0)::bigint AS rating_count,
    EXISTS (
        SELECT 1 FROM product_variants sv
        WHERE sv.product_id = p.id AND sv.is_active
          AND sv.stock_quantity > sv.safety_stock
    ) AS in_stock,
    coalesce(img.storage_key, '') AS image_key,
    coalesce(localized_name(img.alt_text, img.alt_text_en, $1::text), '')::text AS image_alt,
    coalesce(img.width, 0)::integer AS image_width,
    coalesce(img.height, 0)::integer AS image_height,
    cp.orders::bigint AS bought_together
FROM product_copurchases cp
JOIN products p ON p.id = cp.other_product_id
JOIN brands b ON b.id = p.brand_id
JOIN LATERAL (
    SELECT price_cents, compare_at_price_cents
    FROM product_variants
    WHERE product_id = p.id AND is_active
    ORDER BY (stock_quantity > safety_stock) DESC, price_cents
    LIMIT 1
) mv ON true
LEFT JOIN LATERAL (
    SELECT avg(rating)::float8 AS rating, count(*) AS n
    FROM visible_reviews WHERE product_id = p.id
) rv ON true
LEFT JOIN LATERAL (
    SELECT storage_key, alt_text, alt_text_en, width, height
    FROM product_images WHERE product_id = p.id ORDER BY position LIMIT 1
) img ON true
WHERE cp.product_id = $2
  AND cp.orders >= $3::integer
  -- Only what can still be bought. A recommendation slot pointing at an
  -- archived product is a 404 somebody chose to click, and the projection
  -- outlives a product being retired.
  AND p.status = 'active'
ORDER BY cp.orders DESC, p.id
LIMIT $4::integer
`

type BoughtTogetherParams struct {
	Locale    string
	ProductID uuid.UUID
	MinOrders int32
	LimitTo   int32
}

type BoughtTogetherRow struct {
	Slug                string
	Name                string
	Summary             string
	Brand               string
	MinPriceCents       int64
	CompareAtPriceCents pgtype.Int8
	Rating              float64
	RatingCount         int64
	InStock             bool
	ImageKey            string
	ImageAlt            string
	ImageWidth          int32
	ImageHeight         int32
	BoughtTogether      int64
}

// 買了又買, read from the projection.
//
// An indexed lookup, not an aggregation. The per-request version cost 136 ms
// for the most-bought product because order_is_committed() ran once per
// candidate row — 14,963 PL/pgSQL calls for one page view — and grew with order
// history forever. This is 0.04 ms and does not.
//
// The minimum is applied HERE rather than in the projection: what counts as a
// pattern rather than a coincidence is a presentation decision, and baking it
// into the stored rows would mean rebuilding to change it.
func (q *Queries) BoughtTogether(ctx context.Context, arg BoughtTogetherParams) ([]BoughtTogetherRow, error) {
	rows, err := q.db.Query(ctx, boughtTogether,
		arg.Locale,
		arg.ProductID,
		arg.MinOrders,
		arg.LimitTo,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BoughtTogetherRow{}
	for rows.Next() {
		var i BoughtTogetherRow
		if err := rows.Scan(
			&i.Slug,
			&i.Name,
			&i.Summary,
			&i.Brand,
			&i.MinPriceCents,
			&i.CompareAtPriceCents,
			&i.Rating,
			&i.RatingCount,
			&i.InStock,
			&i.ImageKey,
			&i.ImageAlt,
			&i.ImageWidth,
			&i.ImageHeight,
			&i.BoughtTogether,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

