const categoryBySlug = `-- name: CategoryBySlug :one
WITH RECURSIVE trail AS (
    SELECT c.id, c.parent_id, c.slug,
           localized_name(c.name, c.name_en, $2::text) AS name, 0 AS depth
    FROM categories c
    WHERE c.slug = $1
    UNION ALL
    SELECT c.id, c.parent_id, c.slug,
           localized_name(c.name, c.name_en, $2::text), t.depth + 1
    FROM categories c
    JOIN trail t ON c.id = t.parent_id
)
SELECT
    self.id,
    self.name,
    -- Ancestors root-first, which is the order the crumbs render in. Empty for
    -- a root category.
    coalesce(
        (SELECT array_agg(a.slug ORDER BY a.depth DESC) FROM trail a WHERE a.depth > 0),
        ARRAY[]::text[]
    )::text[] AS ancestor_slugs,
    coalesce(
        (SELECT array_agg(a.name ORDER BY a.depth DESC) FROM trail a WHERE a.depth > 0),
        ARRAY[]::text[]
    )::text[] AS ancestor_names
FROM trail self
WHERE self.depth = 0
`

type CategoryBySlugParams struct {
	Slug   string
	Locale string
}

type CategoryBySlugRow struct {
	ID            uuid.UUID
	Name          string
	AncestorSlugs []string
	AncestorNames []string
}

// The category a listing URL names, plus the trail above it for the crumbs.
// Walking upward is bounded by the tree's depth, and categories_acyclic
// guarantees the walk terminates.
// Every name goes through localized_name, the one place that decides which name a
// reader gets. A category name is in the header of every page, so getting it in one
// query and not another shows a visitor Phones at the top and 手機 in the crumb.
func (q *Queries) CategoryBySlug(ctx context.Context, arg CategoryBySlugParams) (CategoryBySlugRow, error) {
	row := q.db.QueryRow(ctx, categoryBySlug, arg.Slug, arg.Locale)
	var i CategoryBySlugRow
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.AncestorSlugs,
		&i.AncestorNames,
	)
	return i, err
}

const categoryDescendants = `-- name: CategoryDescendants :many
WITH RECURSIVE d AS (
    SELECT c.id FROM categories c WHERE c.id = $1
    UNION ALL
    SELECT c.id FROM categories c JOIN d ON c.parent_id = d.id
)
SELECT d.id FROM d
`

// Every category in the subtree rooted at $1, including $1 itself.
//
// A listing shows its descendants' products: /c/accessories holds none of its
// own and the site header links straight to it, so an exact category_id match
// renders an empty page from goen's own navigation.
func (q *Queries) CategoryDescendants(ctx context.Context, id uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, categoryDescendants, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const categoryListing = `-- name: CategoryListing :many
SELECT
    p.slug,
    localized_name(p.name, p.name_en, $1::text) AS name,
    coalesce(localized_name(p.summary, p.summary_en, $1::text), '')::text AS summary,
    b.name AS brand,
    mv.price_cents AS min_price_cents,
    mv.compare_at_price_cents,
    coalesce(rv.rating, 0)::float8 AS rating,
    coalesce(rv.n, 0)::bigint AS rating_count,
    EXISTS (
        SELECT 1 FROM product_variants sv
        WHERE sv.product_id = p.id AND sv.is_active
          AND sv.stock_quantity > sv.safety_stock
    ) AS in_stock,
    coalesce(img.storage_key, '') AS image_key,
    coalesce(localized_name(img.alt_text, img.alt_text_en, $1::text), '')::text AS image_alt,
    coalesce(img.width, 0)::integer AS image_width,
    coalesce(img.height, 0)::integer AS image_height
FROM products p
JOIN brands b ON b.id = p.brand_id
JOIN LATERAL (
    SELECT price_cents, compare_at_price_cents
    FROM product_variants
    WHERE product_id = p.id AND is_active
    -- A buyable variant first: the price on a card is a promise, so it has to
    -- be the price of something a visitor can actually put in a cart.
    ORDER BY (stock_quantity > safety_stock) DESC, price_cents
    LIMIT 1
) mv ON true
LEFT JOIN LATERAL (
    SELECT avg(rating)::float8 AS rating, count(*) AS n
    FROM visible_reviews WHERE product_id = p.id
) rv ON true
LEFT JOIN LATERAL (
    SELECT storage_key, alt_text, alt_text_en, width, height
    FROM product_images WHERE product_id = p.id ORDER BY position LIMIT 1
) img ON true
WHERE p.status = 'active'
  AND p.category_id = ANY($2::uuid[])
  AND ($3::uuid[] = ARRAY[]::uuid[] OR p.brand_id = ANY($3::uuid[]))
  -- One variant satisfies every variant-level filter at once. See note 2.
  AND (
      NOT $4::boolean
      OR EXISTS (
          SELECT 1 FROM product_variants v
          WHERE v.product_id = p.id AND v.is_active
            AND (NOT $5::boolean OR v.stock_quantity > v.safety_stock)
            AND ($6::bigint = 0 OR v.price_cents >= $6::bigint)
            AND ($7::bigint = 0 OR v.price_cents <= $7::bigint)
      )
  )
ORDER BY
    CASE WHEN $8::text = 'price_asc'  THEN mv.price_cents END ASC,
    CASE WHEN $8::text = 'price_desc' THEN mv.price_cents END DESC,
    CASE WHEN $8::text = 'rating'     THEN coalesce(rv.rating, 0) END DESC,
    p.published_at DESC, p.id DESC
LIMIT $10::integer OFFSET $9::integer
`

type CategoryListingParams struct {
	Locale         string
	CategoryIds    []uuid.UUID
	BrandIds       []uuid.UUID
	FilterVariants bool
	InStockOnly    bool
	MinPrice       int64
	MaxPrice       int64
	Sort           string
	PageOffset     int32
	PageSize       int32
}

type CategoryListingRow struct {
	Slug                string
	Name                string
	Summary             string
	Brand               string
	MinPriceCents       int64
	CompareAtPriceCents pgtype.Int8
	Rating              float64
	RatingCount         int64
	InStock             bool
	ImageKey            string
	ImageAlt            string
	ImageWidth          int32
	ImageHeight         int32
}

// One page of a category listing.
//
// Three things here are load-bearing and each is measured in
// docs/decisions/003-listing-read-model.md:
//
//  1. status = 'active' is a LITERAL. The planner cannot prove a parameter is
//     always 'active', so parameterising it loses
//     products_category_published_idx entirely (CLAUDE.md, predictable mistake
//     #10). Verified in the plan, not assumed.
//
//  2. Every variant condition sits inside ONE EXISTS. Splitting them lets each
//     find a different variant, which is how a listing answers "in stock and
//     under NT$10,000" with a product whose cheap variant is sold out and whose
//     available one costs ten times that. The rule fires without any option
//     facets; price and stock alone collide.
//
//  3. Sellable is stock_quantity > safety_stock, never > 0.
//     record_inventory_movement refuses a sale or hold that would breach the
//     floor, so a variant sitting AT it has stock and cannot be bought.
//
// Sorting is chosen by $-parameter rather than composed in Go: an ORDER BY built
// from a request is where an injection gets in, and sqlc would not see it.
func (q *Queries) CategoryListing(ctx context.Context, arg CategoryListingParams) ([]CategoryListingRow, error) {
	rows, err := q.db.Query(ctx, categoryListing,
		arg.Locale,
		arg.CategoryIds,
		arg.BrandIds,
		arg.FilterVariants,
		arg.InStockOnly,
		arg.MinPrice,
		arg.MaxPrice,
		arg.Sort,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CategoryListingRow{}
	for rows.Next() {
		var i CategoryListingRow
		if err := rows.Scan(
			&i.Slug,
			&i.Name,
			&i.Summary,
			&i.Brand,
			&i.MinPriceCents,
			&i.CompareAtPriceCents,
			&i.Rating,
			&i.RatingCount,
			&i.InStock,
			&i.ImageKey,
			&i.ImageAlt,
			&i.ImageWidth,
			&i.ImageHeight,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

