const reorderLines = `-- name: ReorderLines :many
SELECT ol.variant_id, ol.product_name, ol.variant_label, ol.quantity,
       coalesce(pv.is_active AND p.status = 'active', false)::boolean AS sellable,
       coalesce(pv.stock_quantity - pv.safety_stock, 0)::integer AS available
FROM order_lines ol
JOIN orders o ON o.id = ol.order_id
LEFT JOIN product_variants pv ON pv.id = ol.variant_id
LEFT JOIN products p ON p.id = pv.product_id
WHERE o.order_number = $1
ORDER BY ol.position, ol.id
`

type ReorderLinesRow struct {
	VariantID    uuid.NullUUID
	ProductName  string
	VariantLabel pgtype.Text
	Quantity     int32
	Sellable     bool
	Available    int32
}

// An order's lines as a REORDER sees them: what was bought, and what of it can
// still be bought.
//
// LEFT JOIN and not JOIN: order_lines keeps the product name and price it was
// sold at, and variant_id is nullable precisely so a line survives the variant
// being deleted. An order from last year will have some, and dropping those
// rows silently would make the page say it added everything.
func (q *Queries) ReorderLines(ctx context.Context, orderNumber string) ([]ReorderLinesRow, error) {
	rows, err := q.db.Query(ctx, reorderLines, orderNumber)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReorderLinesRow{}
	for rows.Next() {
		var i ReorderLinesRow
		if err := rows.Scan(
			&i.VariantID,
			&i.ProductName,
			&i.VariantLabel,
			&i.Quantity,
			&i.Sellable,
			&i.Available,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const requestEmailVerification = `-- name: RequestEmailVerification :exec
INSERT INTO email_verifications (user_id, email, digest, expires_at)
VALUES ($1, $2::text, $3, now() + $4::interval)
ON CONFLICT (user_id) DO UPDATE
    SET email      = EXCLUDED.email,
        digest     = EXCLUDED.digest,
        expires_at = EXCLUDED.expires_at,
        created_at = now()
`

type RequestEmailVerificationParams struct {
	UserID uuid.UUID
	Email  string
	Digest []byte
	Ttl    pgtype.Interval
}

// Ask for an address to be proved.
//
// Replaces any earlier request for this customer, so a mailbox holds one live link.
// The address is stored as given and compared with lower() at confirmation, the way
// users.email is.
